let toastTimer;
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3200);}
function shapeLabel(value){return t(value);}
function refreshLanguage(){
  document.documentElement.lang=language==='en'?'en':'zh-CN';
  document.title=language==='en'?'Building Geometry Lab · Leidafang':'建筑几何实验室 · Leidafang';
  document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));
  $('language').textContent=language==='en'?'中文':'EN';
  $('language').setAttribute('aria-label',language==='en'?'切换到中文':'Switch to English');
  $('reset-view').title=t('resetView');$('reset-view').setAttribute('aria-label',t('resetView'));
  $('screenshot').title=t('png');$('screenshot').setAttribute('aria-label',t('png'));
  $('scene').setAttribute('aria-label',language==='en'?'3D building. Drag to orbit, scroll to zoom, right-drag to pan.':'三维建筑，拖动旋转、滚轮缩放、右键平移');
  $('plan').setAttribute('aria-label',language==='en'?'Current building footprint':'当前建筑平面轮廓');
  $('gallery').setAttribute('aria-label',language==='en'?'Original Building Tools samples':'Building Tools 原始样例');
  params.forEach(k=>$(k+'-number').setAttribute('aria-label',t(k)));
  syncControls();refreshInfo();renderGallery();
}
function setPanelMode(){
  $('original-panel').hidden=mode!=='original';$('workshop-panel').hidden=mode!=='workshop';
  for(const k of ['original','workshop']){
    $('mode-'+k).classList.toggle('active',mode===k);$('mode-'+k).setAttribute('aria-pressed',String(mode===k));
  }
}
function syncControls(){
  $('shape').value=config.shape;$('roof').value=config.roof;
  const maxArm=Math.min(config.width,config.depth)*.42;
  for(const id of ['arm','arm-number'])$(id).max=String(Math.floor(maxArm*10)/10);
  params.forEach(k=>{
    $(k).value=String(config[k]);$(k+'-number').value=String(config[k]);
    $(k).style.setProperty('--fill',`${100*(config[k]-Number($(k).min))/(Number($(k).max)-Number($(k).min))}%`);
  });
  document.querySelector('[data-control=depth]').hidden=config.shape==='circle';
  document.querySelector('[data-control=arm]').hidden=!['hshape','lshape'].includes(config.shape);
  document.querySelector('[data-control=roofHeight]').hidden=config.shape!=='rectangle'||config.roof==='flat';
  $('roof-control').hidden=config.shape!=='rectangle';
  document.querySelector('label[for=width]').textContent=t(config.shape==='circle'?'diameter':'width');
}
function drawPlan(poly){
  const svg=$('plan'),ns='http://www.w3.org/2000/svg';svg.replaceChildren();
  if(!poly?.length)return;
  const xs=poly.map(p=>p[0]),ys=poly.map(p=>p[1]);
  const lo=[Math.min(...xs),Math.min(...ys)],hi=[Math.max(...xs),Math.max(...ys)];
  const scale=Math.min(188/(hi[0]-lo[0]),107/(hi[1]-lo[1]));
  const map=p=>[120+(p[0]-(lo[0]+hi[0])/2)*scale,72-(p[1]-(lo[1]+hi[1])/2)*scale];
  for(let x=0;x<=240;x+=20){const line=document.createElementNS(ns,'path');line.setAttribute('d',`M${x} 0V150`);line.setAttribute('stroke','#e4e9ec');line.setAttribute('stroke-width','.5');svg.append(line);}
  for(let y=0;y<=150;y+=20){const line=document.createElementNS(ns,'path');line.setAttribute('d',`M0 ${y}H240`);line.setAttribute('stroke','#e4e9ec');line.setAttribute('stroke-width','.5');svg.append(line);}
  const shape=document.createElementNS(ns,'polygon');shape.setAttribute('points',poly.map(p=>map(p).join(',')).join(' '));shape.setAttribute('fill','#9aafbe');shape.setAttribute('stroke','#4f7087');shape.setAttribute('stroke-width','1.3');svg.append(shape);
  const label=document.createElementNS(ns,'text');label.setAttribute('x','120');label.setAttribute('y','144');label.setAttribute('text-anchor','middle');label.textContent=`${fmt(hi[0]-lo[0])} × ${fmt(hi[1]-lo[1])} m`;svg.append(label);
}
function originalName(sample){return sample?.[language==='en'?'name_en':'name_zh']||'';}
function refreshInfo(){
  if(!currentInfo)return;
  const p=currentInfo;
  $('metric-width').textContent=fmt(p.dimensions[0]);$('metric-depth').textContent=fmt(p.dimensions[1]);
  $('metric-height').textContent=fmt(p.dimensions[2]);$('metric-area').textContent=fmt(p.area);$('metric-volume').textContent=fmt(p.volume,0);
  $('engine-label').textContent=mode==='original'?'BUILDING TOOLS / ORIGINAL':'BROWSER WORKSHOP / LIVE';
  $('scene-title').textContent=mode==='original'?`${selected.id} · ${originalName(selected)}`:`${shapeLabel(config.shape)} · ${t(config.roof)}`;
  $('scene-subtitle').textContent=mode==='original'?'Blender 4.0.2 · m':t('units');
  $('geometry-state').textContent=t('geometryOnly');
  if(mode==='original'){
    $('original-title').textContent=originalName(selected);
    const p=selected.parameters;
    const typeNames={'RECTANGULAR':'rectangle','CIRCULAR':'circle','COMPOSITE':'lshape','H-SHAPED':'hshape','RANDOM':null};
    const type=typeNames[p.floorplan.type];
    const rows=[[t('shapeName'),type?t(type):(language==='en'?'Random extensions':'随机扩展')],
      [t('floors'),`${p.floors} ${t('storeyUnit')}`],[t('floorHeight'),`${fmt(p.floor_height)} m`],
      [t('roofFact'),t(p.roof.type.toLowerCase())]];
    $('original-facts').replaceChildren(...rows.map(([key,value])=>{
      const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=key;dd.textContent=value;row.append(dt,dd);return row;
    }));
    $('original-json').textContent=JSON.stringify(selected.parameters,null,2);
  }
  drawPlan(p.footprint);
}
function renderGallery(){
  if(!catalog.length)return;
  $('gallery').replaceChildren(...catalog.map(sample=>{
    const button=document.createElement('button');button.type='button';button.className='sample';
    button.classList.toggle('active',mode==='original'&&selected?.id===sample.id);
    button.setAttribute('aria-pressed',String(mode==='original'&&selected?.id===sample.id));button.dataset.sample=sample.id;
    const imageBox=document.createElement('div');imageBox.className='sample-image';
    const image=document.createElement('img');image.src=sample.preview;image.alt=originalName(sample);image.loading='lazy';image.width=520;image.height=450;
    const index=document.createElement('span');index.className='sample-index';index.textContent=sample.id;
    const arrow=document.createElement('span');arrow.className='sample-arrow';arrow.textContent='↗';imageBox.append(image,index,arrow);
    const copy=document.createElement('div');copy.className='sample-copy';const h=document.createElement('h3');h.textContent=originalName(sample);
    const dims=document.createElement('p');dims.textContent=sample.dimensions_m.map(n=>fmt(n)).join(' × ')+' m';copy.append(h,dims);button.append(imageBox,copy);
    button.addEventListener('click',()=>{selectOriginal(sample);if(window.innerWidth<700)$('lab').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});});return button;
  }));
}
function dispose(object){
  if(!object)return;const geometries=new Set(),materials=new Set();
  object.traverse(o=>{if(o.geometry)geometries.add(o.geometry);if(o.material)(Array.isArray(o.material)?o.material:[o.material]).forEach(m=>materials.add(m));});
  geometries.forEach(g=>g.dispose());materials.forEach(m=>m.dispose());object.removeFromParent();
}
function installModel(next){
  dispose(root);dispose(overlays);root=next;scene.add(root);overlays=new THREE.Group();
  root.updateMatrixWorld(true);
  root.traverse(o=>{
    if(!o.isMesh)return;o.castShadow=true;o.receiveShadow=false;
    const edge=new THREE.LineSegments(new THREE.EdgesGeometry(o.geometry,25),new THREE.LineBasicMaterial({color:0x405e70,transparent:true,opacity:.17}));
    edge.matrixAutoUpdate=false;edge.matrix.copy(o.matrixWorld);overlays.add(edge);
    const wireMesh=new THREE.LineSegments(new THREE.WireframeGeometry(o.geometry),new THREE.LineBasicMaterial({color:0x435e74,transparent:true,opacity:.3}));
    wireMesh.matrixAutoUpdate=false;wireMesh.matrix.copy(o.matrixWorld);wireMesh.visible=wire;wireMesh.userData.wire=true;overlays.add(wireMesh);
  });
  scene.add(overlays);fitCamera();dirty=true;
}
function fitCamera(preset=null){
  if(!root||!webgl)return;
  if(preset)view=preset;
  const box=bounds(),size=box.getSize(new THREE.Vector3()),target=box.getCenter(new THREE.Vector3());
  let direction;
  if(preset==='top')direction=new THREE.Vector3(0,-.0001,1);
  else if(preset==='front')direction=new THREE.Vector3(0,-1,.0001);
  else if(preset==='iso'||!ready)direction=new THREE.Vector3(1.45,-1.8,1.3).normalize();
  else direction=camera.position.clone().sub(controls.target).normalize();
  controls.target.copy(target);camera.position.copy(target).addScaledVector(direction,size.length()*3+40);camera.lookAt(target);
  const right=new THREE.Vector3(1,0,0).applyQuaternion(camera.quaternion),up=new THREE.Vector3(0,1,0).applyQuaternion(camera.quaternion);
  const xs=[],ys=[];
  for(const x of [box.min.x,box.max.x])for(const y of [box.min.y,box.max.y])for(const z of [box.min.z,box.max.z]){
    const p=new THREE.Vector3(x,y,z).sub(target);xs.push(p.dot(right));ys.push(p.dot(up));
  }
  const aspect=$('stage').clientWidth/$('stage').clientHeight;
  const height=Math.max((Math.max(...ys)-Math.min(...ys))*1.4,(Math.max(...xs)-Math.min(...xs))/aspect*1.4,10);
  camera.left=-height*aspect/2;camera.right=height*aspect/2;camera.top=height/2;camera.bottom=-height/2;camera.zoom=1;camera.updateProjectionMatrix();controls.update();
  document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-pressed',String(b.dataset.view===view));});
  dirty=true;
}
function setNativeInfo(sample){
  selected=sample;mode='original';
  currentInfo={dimensions:sample.dimensions_m,area:sample.footprint_area_m2,volume:sample.volume_m3,
    footprint:sample.footprint_xy_m,triangles:sample.triangles,closed:true};
  setPanelMode();refreshInfo();renderGallery();
}
async function selectOriginal(sample){
  const ticket=++revision;$('loading').hidden=false;
  if(!webgl){setNativeInfo(sample);$('poster').src=sample.preview;$('loading').hidden=true;return;}
  try{
    if(!byteCache.has(sample.id)){
      const response=await fetch(new URL(sample.glb,import.meta.url));if(!response.ok)throw Error(`HTTP ${response.status}`);
      byteCache.set(sample.id,await response.arrayBuffer());
    }
    const gltf=await loader.parseAsync(byteCache.get(sample.id).slice(0),'');
    if(ticket!==revision){dispose(gltf.scene);return;}
    const group=new THREE.Group();group.rotation.x=Math.PI/2;group.add(gltf.scene);group.updateMatrixWorld(true);
    const box=new THREE.Box3().setFromObject(group),center=box.getCenter(new THREE.Vector3());
    group.position.set(-center.x,-center.y,-box.min.z);group.updateMatrixWorld(true);
    installModel(group);setNativeInfo(sample);ready=true;$('poster').hidden=true;
  }catch(error){if(ticket===revision){console.error(error);toast(t('failed'));setPanelMode();}}
  finally{if(ticket===revision)$('loading').hidden=true;}
}
function updateWorkshop(values={}){
  ++revision;$('loading').hidden=true;
  const candidate={...config,...values};
  for(const key of params){
    const step=Number($(key).step);
    candidate[key]=Number((Math.round(Number(candidate[key])/step)*step).toFixed(4));
  }
  candidate.arm=Math.min(candidate.arm,Math.floor(Math.min(candidate.width,candidate.depth)*.42*10)/10);
  const result=buildGeometry(candidate);config=result.config;
  const mesh=new THREE.Mesh(result.geometry,[new THREE.MeshStandardMaterial({color:0x8babbc,roughness:.82}),new THREE.MeshStandardMaterial({color:0xad735c,roughness:.88})]);
  mesh.name='browser-workshop-v1';
  if(webgl)installModel(mesh);else{result.geometry.dispose();return;}
  mode='workshop';currentInfo={dimensions:[config.width,config.depth,config.floors*config.floorHeight+(config.roof==='flat'?0:config.roofHeight)],
    area:result.area,volume:result.checks.volume,footprint:result.footprint,triangles:result.checks.triangles,closed:result.checks.closed,checks:result.checks};
  ready=true;$('poster').hidden=true;setPanelMode();syncControls();refreshInfo();renderGallery();
}
function initialize3d(){
  scene=new THREE.Scene();scene.background=new THREE.Color(0xeef1f3);
  camera=new THREE.OrthographicCamera(-30,30,25,-25,.01,2000);camera.up.set(0,0,1);
  renderer=new THREE.WebGLRenderer({canvas:$('scene'),antialias:true,preserveDrawingBuffer:true,alpha:false});
  renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
  renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.35;
  scene.add(new THREE.HemisphereLight(0xe7f1ff,0x8c969b,2.6));
  light=new THREE.DirectionalLight(0xffe8d6,3.4);light.position.set(-35,-30,65);light.castShadow=true;
  light.shadow.mapSize.set(2048,2048);Object.assign(light.shadow.camera,{left:-65,right:65,top:65,bottom:-65,near:.1,far:220});
  light.shadow.normalBias=.035;light.shadow.bias=-.0001;scene.add(light);
  const fill=new THREE.DirectionalLight(0xddeeff,1.2);fill.position.set(30,10,30);scene.add(fill);
  const ground=new THREE.Mesh(new THREE.PlaneGeometry(2000,2000),new THREE.MeshStandardMaterial({color:0xe9edef,roughness:1}));
  ground.position.z=-.025;ground.receiveShadow=true;scene.add(ground);
  const grid=new THREE.GridHelper(100,20,0xa1b0ba,0xc1ccd3);grid.rotation.x=Math.PI/2;grid.position.z=-.018;
  grid.material.transparent=true;grid.material.opacity=.32;scene.add(grid);
  controls=new OrbitControls(camera,$('scene'));controls.enableDamping=true;controls.dampingFactor=.1;controls.enablePan=true;controls.autoRotateSpeed=.65;controls.minZoom=.2;controls.maxZoom=6;controls.listenToKeyEvents($('scene'));
  controls.addEventListener('change',()=>dirty=true);
  const resize=()=>{
    const stage=$('stage');renderer.setSize(stage.clientWidth,stage.clientHeight,false);fitCamera();dirty=true;
  };
  new ResizeObserver(resize).observe($('stage'));resize();
  const clock=new THREE.Clock();
  renderer.setAnimationLoop(()=>{
    const delta=Math.min(clock.getDelta(),.05);const changed=controls.update(delta);
    if(dirty||changed||controls.autoRotate){renderer.render(scene,camera);renderCount++;dirty=false;}
  });
  $('scene').addEventListener('webglcontextlost',event=>{event.preventDefault();ready=false;toast(t('no3d'));});
}
function download(blob,name){const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('saved'));}
function downloadOriginal(url,name){const a=document.createElement('a');a.href=url;a.download=name;a.click();}
async function exportModel(kind){
  const button=$('download-'+kind);button.disabled=true;
  try{
    if(kind==='json'){
      const value=mode==='original'?{generator:'Building Tools',version:'v1.0.13',...selected,units:'metres',training_eligible:false}:exportParameters(config,currentInfo.checks);
      download(new Blob([JSON.stringify(value,null,2)+'\n'],{type:'application/json'}),`geometry-${mode==='original'?selected.id:config.shape}.json`);
    }else if(mode==='original')downloadOriginal(selected[kind],`${selected.id}-building.${kind}`);
    else if(kind==='stl'){
      const {STLExporter}=await import('./vendor/exporters/STLExporter.js');
      const data=new STLExporter().parse(root,{binary:true});download(new Blob([data],{type:'application/octet-stream'}),`workshop-${config.shape}.stl`);
    }else{
      const {GLTFExporter}=await import('./vendor/exporters/GLTFExporter.js');
      const wrapper=new THREE.Group();wrapper.rotation.x=-Math.PI/2;wrapper.add(root.clone(true));
      const buffer=await new GLTFExporter().parseAsync(wrapper,{binary:true});
      download(new Blob([buffer],{type:'model/gltf-binary'}),`workshop-${config.shape}.glb`);
    }
  }catch(error){console.error(error);toast(t('exportFailed'));}finally{button.disabled=false;}
}
$('language').addEventListener('click',()=>{language=language==='zh'?'en':'zh';try{localStorage.setItem('building-geometry-language',language);}catch{}refreshLanguage();});
$('mode-original').addEventListener('click',()=>selectOriginal(selected||catalog[6]));
function enterWorkshop(){
  if(!webgl){toast(t('no3d'));return;}
  if(mode==='workshop')return;
  const p=selected?.parameters;
  if(p){
    const shape={'RECTANGULAR':'rectangle','CIRCULAR':'circle','COMPOSITE':'lshape','H-SHAPED':'hshape','RANDOM':'lshape'}[p.floorplan.type];
    config={...defaults,shape,width:Math.min(48,Math.max(8,selected.dimensions_m[0]-.3)),depth:Math.min(48,Math.max(8,selected.dimensions_m[1]-.3)),floors:p.floors,floorHeight:p.floor_height,roof:shape==='rectangle'?p.roof.type.toLowerCase():'flat',roofHeight:p.roof.height||3};
  }
  updateWorkshop();
}
$('mode-workshop').addEventListener('click',enterWorkshop);$('open-workshop').addEventListener('click',enterWorkshop);
$('shape').addEventListener('change',()=>updateWorkshop({shape:$('shape').value}));$('roof').addEventListener('change',()=>updateWorkshop({roof:$('roof').value}));
for(const key of params){
  $(key).addEventListener('input',()=>updateWorkshop({[key]:Number($(key).value)}));
  $(key+'-number').addEventListener('change',()=>{
    const input=$(key+'-number');if(!input.checkValidity()){input.reportValidity();syncControls();return;}
    updateWorkshop({[key]:Number(input.value)});
  });
}
$('shuffle').addEventListener('click',()=>updateWorkshop({width:Math.round(12+Math.random()*24),depth:Math.round(12+Math.random()*24),floors:2+Math.floor(Math.random()*10),floorHeight:3.2,arm:2+Math.random()*3,roof:config.shape==='rectangle'?['flat','gable','hip'][Math.floor(Math.random()*3)]:'flat',roofHeight:Math.round((1+Math.random()*5)*10)/10}));
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>fitCamera(b.dataset.view)));
$('reset-view').addEventListener('click',()=>fitCamera('iso'));
$('wireframe').addEventListener('click',()=>{wire=!wire;overlays?.traverse(o=>{if(o.userData.wire)o.visible=wire;});$('wireframe').setAttribute('aria-pressed',String(wire));dirty=true;});
$('rotate').addEventListener('click',()=>{if(!controls)return;controls.autoRotate=!controls.autoRotate;$('rotate').setAttribute('aria-pressed',String(controls.autoRotate));dirty=true;});
for(const kind of ['json','glb','stl'])$('download-'+kind).addEventListener('click',()=>exportModel(kind));
$('screenshot').addEventListener('click',()=>{if(!renderer)return;renderer.render(scene,camera);renderer.domElement.toBlob(blob=>{if(blob)download(blob,'building-geometry.png');},'image/png');});

window.__geometryDiagnostics=()=>({ready,mode,sample:mode==='original'?selected?.id:null,config:{...config},
  dimensions:currentInfo?.dimensions,volume:currentInfo?.volume,area:currentInfo?.area,closed:currentInfo?.closed,
  triangles:currentInfo?.triangles,renderCount,view,wire,autoRotate:controls?.autoRotate||false,
  actualDimensions:root?bounds().getSize(new THREE.Vector3()).toArray():null,
  camera:camera?.position.toArray(),language,revision,renderer:renderer?.getContext().getParameter(renderer.getContext().RENDERER)});

async function boot(){
  refreshLanguage();
  try{initialize3d();}catch(error){webgl=false;$('loading').hidden=true;toast(t('no3d'));console.warn('WebGL initialization unavailable');}
  try{
    const response=await fetch(new URL('./assets/catalog.json',import.meta.url));if(!response.ok)throw Error('Catalog unavailable');
    const data=await response.json();catalog=data.samples;renderGallery();await selectOriginal(catalog[6]);
  }catch(error){console.error(error);$('loading').hidden=true;toast(t('failed'));}
}
boot();
